import java.util.*;

public class Main {
    static class Edge {
        int y, capacity, flow, cost;
        Edge() {}
        Edge(int y, int c, int f, int cost) {
            this.y = y;
            this.capacity = c;
            this.flow = f;
            this.cost = cost;
        }
    }

    static List<Edge> network = new ArrayList<>();
    static final int MAXN = 14043;
    static List<Integer>[] adj = new ArrayList[MAXN];

    static long total_cost = 0;
    static long[] dist = new long[MAXN];
    static int[] parent_node = new int[MAXN];
    static int[] parent_edge = new int[MAXN];
    static int[] inq = new int[MAXN];

    static final long INF = (long)1e18;
    static int s = MAXN - 2;
    static int t = MAXN - 1;

    static int residual(int idx) {
        return network.get(idx).capacity - network.get(idx).flow;
    }

    static void find_path() {
        Arrays.fill(dist, INF);
        Arrays.fill(parent_node, -1);
        Arrays.fill(parent_edge, -1);
        Arrays.fill(inq, 0);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        inq[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inq[u] = 0;
            for (int e_idx : adj[u]) {
                if (residual(e_idx) == 0) continue;
                int y = network.get(e_idx).y;
                int cst = network.get(e_idx).cost;
                if (dist[y] > dist[u] + cst) {
                    dist[y] = dist[u] + cst;
                    parent_node[y] = u;
                    parent_edge[y] = e_idx;
                    if (inq[y] == 0) {
                        inq[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int cur = t;
        while (cur != s) {
            network.get(parent_edge[cur]).flow++;
            network.get(parent_edge[cur] ^ 1).flow--;
            cur = parent_node[cur];
        }
        total_cost += dist[t];
    }

    static void add_link(int from, int to, int cap, int cst) {
        adj[from].add(network.size());
        network.add(new Edge(to, cap, 0, cst));
        adj[to].add(network.size());
        network.add(new Edge(from, 0, 0, -cst));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            add_link(s, x, 1, 0);
        }

        int T = 101;
        for (int i = 0; i < T; i++) {
            add_link(i * n, t, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int j = 0; j < T - 1; j++) {
                for (int l = 0; l < k; l++) {
                    add_link(x + j * n, y + j * n + n, 1, d * (l * 2 + 1));
                }
            }
            for (int j = 0; j < T - 1; j++) {
                for (int l = 0; l < k; l++) {
                    add_link(y + j * n, x + j * n + n, 1, d * (l * 2 + 1));
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                add_link(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            find_path();
        }

        System.out.println(total_cost);
        sc.close();
    }
}
